def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [
        fmt([4]), fmt([3]), fmt([-4]), fmt([-3]), fmt([0]), fmt([1, 1]), fmt([3, 2, 5, 8, 1]),
        fmt([9, -1, 2]), fmt([7, -3, -9]), fmt([-1, -3, -5]), fmt([1, 3, 5]), fmt([2, 4, 6]),
        fmt([5, -5]), fmt([-2, -4, 3]),
    ]
    for n in range(2, 15):
        for _ in range(2):
            hi = rng.choice([3, 9, 50])
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    n = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(n)]))
    tests.append(fmt([rng.randint(1, 10**9) for _ in range(n)]))
    tests.append(fmt([rng.randint(-10**9, -1) for _ in range(n)]))
    tests.append(fmt([2 * rng.randint(0, 5 * 10**8) + 1 for _ in range(n)]))
    return tests

